const student = $input.all()[0].json;
const ai = $('Switch').item.json.body;

if (!student.StudentID) {
  return [{ json: { 
    error: true,
    reply: `Student ${ai.studentName} not found. Register them first.`
  }}];
}

const hwId = 'HW' + Date.now().toString().slice(-4);

const cleanDate = (d) => {
  if (!d) return ai.today;
  return d.split('T')[0];
};

return [{
  json: {
    error:        false,
    homeworkId:   hwId,
    studentId:    student.StudentID,
    studentName:  student.Name.split(' ')[0],
    subject:      ai.subject,
    description:  ai.description,
    assignedDate: ai.today,
    dueDate:      cleanDate(ai.dueDate),
    status:       'Assigned'
  }
}];

const items = $input.all();
const studentName = $('Switch').item.json.body.studentName;

if (!items.length || !items[0].json.StudentName) {
  return [{ json: { reply: `No homework found for ${studentName}.` } }];
}

const list = items.map(item => {
  const date = item.json.DueDate ? item.json.DueDate.split('T')[0] : 'No date';
  return `${item.json.Subject}: ${item.json.Description} (Due: ${date}) - ${item.json.Status || 'Assigned'}`;
}).join('\n');

return [{ json: { reply: `Homework for ${items[0].json.StudentName}:\n${list}` } }];

const webhook = $('Webhook').first().json.body;

// Get fee data from the Get Fees node we added before Update
const feeData = $('Get row(s) in sheet1').first().json;

const now       = new Date();
const receiptNo = 'RCP' + Date.now().toString().slice(-6);

const amountDue  = feeData.AmountDue  || 'N/A';
const amountPaid = webhook.mode === 'paid'
  ? amountDue
  : (webhook.amountPaid || 'N/A');

const month = feeData.Month || webhook.currentMonth || '';

const receipt = [
  '━━━━━━━━━━━━━━━━━━━━━━━',
  '      PAYMENT RECEIPT',
  '━━━━━━━━━━━━━━━━━━━━━━━',
  `Receipt No:    ${receiptNo}`,
  `Date:          ${now.toLocaleDateString('en-GB')}`,
  `Time:          ${now.toLocaleTimeString('en-GB')}`,
  '───────────────────────',
  `Student:       ${webhook.studentName}`,
  `Month:         ${month}`,
  `Amount Due:    PKR ${amountDue}`,
  `Amount Paid:   PKR ${amountPaid}`,
  `Status:        ${webhook.mode === 'paid' ? 'PAID IN FULL' : 'PARTIAL PAYMENT'}`,
  webhook.transactionId
    ? `Transaction:   ${webhook.transactionId}`
    : '',
  '───────────────────────',
  'Payment Method: JazzCash',
  '━━━━━━━━━━━━━━━━━━━━━━━',
  'Thank you for your payment!'
].filter(Boolean).join('\n');

return [{
  json: {
    receipt:         receipt,
    studentName:     webhook.studentName,
    parentDiscordId: feeData.ParentDiscordID || ''
  }
}];
